import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Stack;

public class StackBasics {

    // 1. 括号匹配：遇到左括号入栈，遇到右括号弹栈比对
    public static boolean isValid(String s) {
        Deque<Character> stack = new ArrayDeque<>();
        for (char c : s.toCharArray()) {
            if (c == '(' || c == '[' || c == '{') {
                stack.push(c);
            } else {
                if (stack.isEmpty()) return false;
                char top = stack.pop();
                if ((c == ')' && top != '(') ||
                    (c == ']' && top != '[') ||
                    (c == '}' && top != '{')) {
                    return false;
                }
            }
        }
        return stack.isEmpty(); // 全部匹配完才算合法
    }

    // 2. 用两个栈实现队列（摊还 O(1)）
    static class MyQueue {
        private Deque<Integer> stackIn = new ArrayDeque<>();
        private Deque<Integer> stackOut = new ArrayDeque<>();

        public void push(int x) { stackIn.push(x); }

        public int pop() {
            transferIfNeeded();
            return stackOut.pop();
        }

        public int peek() {
            transferIfNeeded();
            return stackOut.peek();
        }

        private void transferIfNeeded() {
            if (stackOut.isEmpty()) {
                while (!stackIn.isEmpty()) {
                    stackOut.push(stackIn.pop()); // 反转顺序
                }
            }
        }

        public boolean empty() {
            return stackIn.isEmpty() && stackOut.isEmpty();
        }
    }

    // 3. 单调栈：每日温度（LeetCode 739）
    // 栈里存下标，维护从栈底到栈顶温度递减的单调栈
    public static int[] dailyTemperatures(int[] temperatures) {
        int n = temperatures.length;
        int[] result = new int[n];
        Deque<Integer> stack = new ArrayDeque<>(); // 存下标

        for (int i = 0; i < n; i++) {
            while (!stack.isEmpty()
                   && temperatures[i] > temperatures[stack.peek()]) {
                int prevIdx = stack.pop();
                result[prevIdx] = i - prevIdx; // 距离
            }
            stack.push(i);
        }
        return result;
    }

    // 4. 后缀表达式求值（逆波兰表达式）
    public static int evalRPN(String[] tokens) {
        Deque<Integer> stack = new ArrayDeque<>();
        for (String token : tokens) {
            if (token.equals("+") || token.equals("-") ||
                token.equals("*") || token.equals("/")) {
                int b = stack.pop(); // 注意操作数顺序
                int a = stack.pop();
                switch (token) {
                    case "+": stack.push(a + b); break;
                    case "-": stack.push(a - b); break;
                    case "*": stack.push(a * b); break;
                    case "/": stack.push(a / b); break;
                }
            } else {
                stack.push(Integer.parseInt(token));
            }
        }
        return stack.pop();
    }
}
